/* From Uiverse.io by amralashi - Tags: button */
.__UIV_SCOPE__ button {
  width: 10rem;
  height: 3rem;
  background: linear-gradient(135deg, purple, pink, blue, aqua);
  border-radius: 3rem;
  font-size: 16px;
  font-weight: 600;
  color: white;
  border: none;
}

.__UIV_SCOPE__ button:hover {
  background: linear-gradient(100deg, purple, pink, blue, aqua);
}
